// Auto-generated for the Unit Board — AWL Sublist 10
window.A10_DASHBOARD_UNITS = [{"unit":1,"theme":"adjacent to – persuade","cards":[{"w":"adjacent to","p":"prep.","d":"next to something","c":"鄰近的","s":"The park adjacent to our house is always bustling with activity.","t":"我們家附近的公園總是熙來攘往。"},{"w":"albeit","p":"conj.","d":"although","c":"雖然","s":"He agreed to come, albeit reluctantly.","t":"他同意來了，雖然有些不情願。"},{"w":"assemble","p":"v.","d":"to put the parts of something together","c":"組裝","s":"They assemble the furniture according to the instructions provided.","t":"他們根據提供的說明組裝家具。"},{"w":"assembly","p":"n.","d":"a meeting of many people","c":"集會","s":"The school assembly was scheduled for Friday morning.","t":"學校集會定於星期五早上。"},{"w":"the assembly line","p":"n.phr.","d":"a line of workers and machines making products","c":"生產線","s":"The assembly line was automated to increase efficiency.","t":"生產線是自動化的，以提高效率。"},{"w":"collapse","p":"v.","d":"to fall down suddenly","c":"倒塌","s":"The building might collapse if the fire continues to spread.","t":"如果火勢繼續蔓延，建築物可能會倒塌。"},{"w":"collapse","p":"n.","d":"a sudden fall or failure","c":"倒塌","s":"The collapse of the roof caused panic among the residents.","t":"屋頂的倒塌使居民恐慌。"},{"w":"league","p":"n.","d":"a group of sports teams","c":"聯盟","s":"The teams were competing for the championship of the league.","t":"這些隊伍正在爭奪聯盟冠軍。"},{"w":"colleague","p":"n.","d":"a person you work with","c":"同事","s":"My colleague helped me when I was overwhelmed with work.","t":"我淹沒在工作中時，我的同事幫助了我。"},{"w":"compile","p":"v.","d":"to collect information into a book or list","c":"編輯","s":"They plan to compile a comprehensive report by the end of the month.","t":"他們計劃在月底前編輯一份全面的報告。"},{"w":"compiled","p":"adj.","d":"collected together","c":"已編輯的","s":"The compiled data was presented in a clear and organized manner.","t":"已編輯的數據以清晰有條理的方式呈現。"},{"w":"compilation","p":"n.","d":"a collection of things put together","c":"編輯","s":"The compilation of essays was published to critical acclaim.","t":"這本文章的編輯得到了好評。"},{"w":"conceive","p":"v.","d":"to think of a new idea","c":"構想","s":"She could not conceive of a better way to solve the problem.","t":"她想不出更好的方法來解決這個問題。"},{"w":"conceived","p":"adj.","d":"thought of; planned","c":"構想的","s":"It was a newly conceived idea that had a lot of potentials.","t":"這是一個具有很多潛力的新構想。"},{"w":"convince","p":"v.","d":"to make someone believe something","c":"使確信","s":"It took a while to convince him that the plan would work.","t":"花了一些時間使他相信計劃會奏效。"},{"w":"convincing","p":"adj.","d":"making you believe something is true","c":"有說服力的","s":"Her argument was convincing, swaying the opinions of many.","t":"她的論點令人信服，影響了很多人的看法。"},{"w":"unconvincing","p":"adj.","d":"not making you believe something","c":"不具有說服力的","s":"The evidence provided was unconvincing, causing doubt among the jury.","t":"提供的證據不具說服力，使陪審團產生懷疑。"},{"w":"convinced","p":"adj.","d":"completely sure","c":"確信的","s":"She was convinced that she had made the right decision.","t":"她確信她做出了正確的決定。"},{"w":"persuade","p":"v.","d":"to make someone agree to do something","c":"說服","s":"They managed to persuade her to join the team.","t":"他們成功地說服她加入了團隊"}]},{"unit":2,"theme":"persuasive – incline","cards":[{"w":"persuasive","p":"adj.","d":"able to make people agree","c":"有說服力的","s":"His persuasive speech motivated many to take action.","t":"他有說服力的演講激勵了許多人採取行動。"},{"w":"persuasion","p":"n.","d":"the act of making people agree","c":"說服","s":"Through gentle persuasion, he got everyone to agree.","t":"通過溫和的說服，他讓每個人都同意了。"},{"w":"depress","p":"v.","d":"to make someone feel sad","c":"使沮喪","s":"The bad news began to depress her.","t":"壞消息開始使她感到沮喪。"},{"w":"depressed","p":"adj.","d":"very sad and without hope","c":"沮喪的","s":"He felt depressed after hearing about the accident.","t":"聽到事故的消息後，他感到很沮喪。"},{"w":"depressing","p":"adj.","d":"making you feel sad","c":"令人沮喪的","s":"The gloomy weather made the day feel depressing.","t":"陰沉的天氣使得一天感覺很沮喪。"},{"w":"depression","p":"n.","d":"a mental illness that makes people very sad","c":"抑鬱症","s":"She sought professional help to deal with her depression.","t":"她尋求專業幫助以應對她的抑鬱症。"},{"w":"encourage","p":"v.","d":"to give someone hope and support","c":"鼓勵","s":"They encourage each other to keep pursuing their dreams.","t":"他們互相鼓勵，繼續追求自己的夢想。"},{"w":"encountered","p":"v.","d":"met something difficult or unexpected","c":"遇到","s":"They encountered some challenges along the way.","t":"他們在路上遇到了一些挑戰。"},{"w":"encouraging","p":"adj.","d":"giving hope and support","c":"鼓勵的","s":"The positive feedback was very encouraging to the team.","t":"積極的反饋對團隊來說非常鼓舞。"},{"w":"encouragement","p":"n.","d":"words or actions that give hope","c":"鼓勵","s":"With a little encouragement, he felt ready to try again.","t":"在一些鼓勵的支持下，他覺得準備好再次嘗試。"},{"w":"discourage from","p":"v. phrase","d":"to make someone not want to do something","c":"使氣餒","s":"His failure did not discourage from him from trying again.","t":"他的失敗並未使他氣餒，不再嘗試。"},{"w":"discouraged","p":"adj.","d":"having lost hope","c":"氣餒的","s":"She felt discouraged after the rejection but decided to keep applying.","t":"面對拒絕，她感到很氣餒，但決定繼續申請。"},{"w":"discouraging","p":"adj.","d":"making you lose hope","c":"令人氣餒的","s":"The news was discouraging, but they remained hopeful.","t":"這消息令人氣餒，但他們仍保持希望。"},{"w":"discouragement","p":"n.","d":"a feeling of having lost hope","c":"氣餒","s":"Despite the discouragement, they were determined to continue working hard.","t":"儘管感到氣餒，他們仍決定繼續努力工作。"},{"w":"enormous","p":"adj.","d":"extremely large","c":"巨大的","s":"The project required an enormous amount of time and resources.","t":"該項目需要大量的時間和資源。"},{"w":"enormously","p":"adv.","d":"extremely; very much","c":"非常","s":"The new policy benefited the community enormously.","t":"新政策對社區的好處非常大。"},{"w":"tremendous","p":"adj.","d":"very great or large","c":"巨大的","s":"The storm caused tremendous damage to the coastal areas.","t":"暴風雨對沿海地區造成了巨大的損害。"},{"w":"forthcoming","p":"adj.","d":"going to happen soon","c":"即將到來的","s":"They are preparing for the forthcoming event with great enthusiasm.","t":"他們正急切地準備即將到來的事件。"},{"w":"incline","p":"v.","d":"to tend to think or act in a certain way","c":"傾向於","s":"I incline to agree with his assessment of the situation.","t":"我傾向於同意他對情況的評估。"}]},{"unit":3,"theme":"be inclined to – similarly","cards":[{"w":"be inclined to","p":"phr","d":"to be likely to do something","c":"傾向於","s":"She was inclined to accept the offer after considering all factors.","t":"考慮了所有因素後，她傾向於接受這個提議。"},{"w":"inclination","p":"n.","d":"a feeling that makes you want to do something","c":"傾向","s":"His inclination towards music was evident from a young age.","t":"他從小就對音樂有明顯的傾向。"},{"w":"decline","p":"v.","d":"to politely say no","c":"拒絕","s":"She had to decline the invitation due to prior commitments.","t":"由於先前的承諾，她不得不拒絕了邀請。"},{"w":"decline","p":"n.","d":"a fall in amount or quality","c":"下降","s":"There has been a significant decline in sales this quarter.","t":"這個季度的銷售顯著下降。"},{"w":"recline","p":"v.","d":"to lean or lie back","c":"斜靠","s":"He chose to recline his seat and rest for a while.","t":"他選擇斜靠座椅休息一會兒。"},{"w":"reclining seat","p":"n.phr.","d":"a seat that can lean back","c":"可倒背的座椅","s":"The airplane was equipped with reclining seat for a more comfortable journey.","t":"飛機配備了可倒背的座椅，以便旅途更舒適。"},{"w":"integrity","p":"n.","d":"being honest and having strong moral rules","c":"正直","s":"His integrity was admired by everyone who knew him.","t":"每個認識他的人都欣賞他的正直。"},{"w":"integrate","p":"v.","d":"to combine things to work together","c":"整合","s":"They aim to integrate the new members into the team smoothly.","t":"他們的目標是平滑地將新成員整合到團隊中。"},{"w":"integrated","p":"adj.","d":"combined into one system","c":"整合的","s":"The program provided an integrated approach to learning.","t":"該計劃提供了一個整合的學習方法。"},{"w":"integration","p":"n.","d":"the act of combining things together","c":"整合","s":"The integration of different systems required careful planning.","t":"不同系統的整合需要仔細的規劃。"},{"w":"intrinsic","p":"adj.","d":"belonging naturally to something","c":"固有的","s":"The intrinsic value of the artwork is immeasurable.","t":"藝術品的固有價值無法衡量。"},{"w":"extrinsic","p":"adj.","d":"coming from outside","c":"外在的","s":"Her motivation to study was extrinsic, driven by the promise of a scholarship.","t":"她學習的動力是外在的，是為了獲得獎學金的承諾。"},{"w":"invoke","p":"v.","d":"to bring a feeling or idea to mind","c":"喚起","s":"The speaker's words managed to invoke strong emotions in the audience.","t":"演講者的話成功地喚起了觀眾的強烈情感。"},{"w":"invoked","p":"adj.","d":"called up or brought to mind","c":"已喚起的","s":"The ancient ritual invoked the spirits of the ancestors.","t":"這個古老的儀式已經喚起了祖先的靈魂。"},{"w":"provoke","p":"v.","d":"to cause a strong feeling or reaction","c":"激起","s":"His actions managed to provoke a heated argument.","t":"他的行為成功地激起了一場激烈的爭論。"},{"w":"provocative","p":"adj.","d":"meant to make people angry","c":"挑釁的","s":"Her provocative comments upset many people in the room.","t":"她挑釁的言論讓房間裡的很多人感到不滿。"},{"w":"impose a levy on","p":"v. phrase","d":"to make people pay a tax on something","c":"徵收稅款於","s":"The government decided to impose a levy on luxury cars to generate revenue.","t":"政府決定對奢侈汽車徵收稅款以產生收入。"},{"w":"likewise","p":"adv.","d":"in the same way","c":"同樣地","s":"He believes in hard work, and likewise, his team members share the same philosophy.","t":"他相信努力工作，同樣地，他的團隊成員也有相同的理念。"},{"w":"similarly","p":"adv.","d":"in the same way","c":"同樣地","s":"The two projects are similarly challenging and require dedication.","t":"這兩個項目同樣具有挑戰性，需要奉獻精神。"}]},{"unit":4,"theme":"in the similar manner – reluctance","cards":[{"w":"in the similar manner","p":"phr.","d":"in a similar way","c":"以相似的方式","s":"Both artists approach their work in the similar manner, focusing on intricate details.","t":"兩位藝術家都以相似的方式處理他們的作品，注重細節。"},{"w":"nonetheless","p":"adv.","d":"however; even so","c":"儘管如此","s":"It was a challenging journey; nonetheless, they reached their destination.","t":"這是一段具有挑戰性的旅程；儘管如此，他們抵達了目的地。"},{"w":"nevertheless","p":"adv.","d":"however; even so","c":"然而","s":"The weather was harsh; nevertheless, they decided to continue the hike.","t":"天氣很惡劣；然而，他們決定繼續徒步旅行。"},{"w":"notwithstanding","p":"adv.","d":"in spite of","c":"雖然","s":"notwithstanding the obstacles, they achieved their goals.","t":"雖然存在障礙，他們實現了自己的目標。"},{"w":"odd","p":"adj.","d":"strange or unusual","c":"奇怪的","s":"His odd behavior raised eyebrows among his colleagues.","t":"他奇怪的行為在同事中引起了疑問。"},{"w":"odds","p":"n.","d":"the chance that something will happen","c":"機會","s":"Despite the odds, they managed to win the game.","t":"儘管機會渺茫，他們還是贏得了比賽。"},{"w":"be at odds","p":"v. phrase","d":"to disagree with someone","c":"不和","s":"They often are at odds with each other about trivial matters.","t":"他們經常因小事而不和。"},{"w":"ongoing","p":"adj.","d":"continuing; still happening","c":"持續的","s":"The project is ongoing and requires constant attention.","t":"這個項目正在持續進行，需要不斷的關注。"},{"w":"panel","p":"n.","d":"a group of experts who discuss something","c":"專家小組","s":"The panel of experts discussed the latest research findings.","t":"專家小組討論了最新的研究發現。"},{"w":"panel discussion","p":"n.phr.","d":"a public talk by a group of experts","c":"座談會","s":"The panel discussion was insightful, covering various aspects of the topic.","t":"座談會非常有見地，涵蓋了該主題的各個方面。"},{"w":"persist in","p":"v. phrase","d":"to keep doing something even when it is hard","c":"堅持","s":"She decided to persist in her efforts despite the challenges.","t":"儘管面臨挑戰，她決定堅持自己的努力。"},{"w":"persistent","p":"adj.","d":"continuing for a long time; not giving up","c":"堅持的","s":"His persistent pursuit of knowledge led to remarkable achievements.","t":"他對知識的堅持追求帶來了卓越的成就。"},{"w":"persistence","p":"n.","d":"the quality of not giving up","c":"堅持","s":"His persistence paid off when he finally achieved his long-term goal.","t":"他的堅持最終在實現他的長期目標時取得了成果。"},{"w":"insist on","p":"v. phrase","d":"to say firmly that something must happen","c":"堅持","s":"She would always insist on quality in her work, no matter the circumstances.","t":"無論情況如何，她總是堅持工作質量。"},{"w":"insist that","p":"v. phrase","d":"to say firmly that something is true","c":"堅持","s":"He insist that it was essential to follow safety protocols.","t":"他堅持遵守安全規程是必要的。"},{"w":"insistent","p":"adj.","d":"not taking no for an answer","c":"堅持的","s":"His insistent demands for improvement led to positive changes.","t":"他對改進的堅持要求帶來了積極的變化。"},{"w":"pose a threat/risk to","p":"phr.","d":"to be dangerous to something","c":"對...構成威脅/風險","s":"The cyberattack could pose a threat to the security of sensitive data.","t":"網絡攻擊可能對敏感數據的安全構成威脅。"},{"w":"posed","p":"v.","d":"asked a question; caused a problem","c":"提出","s":"The question he posed challenged the conventional wisdom.","t":"他提出的問題挑戰了傳統智慧。"},{"w":"reluctance","p":"n.","d":"not wanting to do something","c":"不情願","s":"His reluctance to participate in the project was evident.","t":"他參加該項目的不情願顯而易見。"}]},{"unit":5,"theme":"reluctant – whereby","cards":[{"w":"reluctant","p":"adj.","d":"not wanting to do something","c":"不情願的","s":"She was reluctant to accept the responsibility but eventually agreed.","t":"她不情願承擔責任，但最終同意了。"},{"w":"reluctantly","p":"adv.","d":"in a way that shows you don't want to","c":"不情願地","s":"He reluctantly agreed to attend the event, even though he had reservations.","t":"他不情願地同意參加該活動，儘管心存疑慮。"},{"w":"so called","p":"adj.","d":"named this way, often wrongly","c":"所謂的","s":"The so called \"experts\" turned out to have limited knowledge.","t":"所謂的“專家”事實上知識有限。"},{"w":"straightforward","p":"adj.","d":"simple and easy to understand","c":"直接的","s":"Her straightforward approach to problem-solving was highly effective.","t":"她對解決問題的直接方法非常有效。"},{"w":"undergo","p":"v.","d":"to experience a change or difficulty","c":"經歷","s":"She had to undergo a challenging training program before joining the team.","t":"在加入團隊之前，她必須經歷一個具有挑戰性的培訓課程。"},{"w":"undergoing","p":"adj.","d":"in the process of experiencing something","c":"正在經歷","s":"The company is currently undergoing significant changes in its structure.","t":"公司目前正在經歷結構方面的重大變化。"},{"w":"undertake (do)","p":"v.","d":"to agree to do a job","c":"承諾","s":"He decided to undertake the responsibility of leading the project.","t":"他決定承擔領導該項目的責任。"},{"w":"undertake (promise)","p":"v.","d":"to promise to do something","c":"承諾","s":"She undertook to support the charitable cause with a significant donation.","t":"她承諾捐贈大筆資金支持慈善事業。"},{"w":"undertaking","p":"n.","d":"a big job or project","c":"事業","s":"Starting a new business is a significant undertaking that requires careful planning.","t":"開展新業務是一個需要仔細規劃的重要事業。"},{"w":"undermine","p":"v.","d":"to make something weaker over time","c":"破壞","s":"His actions could undermine the trust and unity within the team.","t":"他的行為可能會破壞團隊內的信任和團結。"},{"w":"underrated","p":"adj.","d":"not valued as much as it should be","c":"低估的","s":"She believed that the artist was underrated and deserved more recognition.","t":"她認為這位藝術家被低估了，應該得到更多的認可。"},{"w":"underlying","p":"adj.","d":"real but not easy to see","c":"潛在的","s":"There are underlying issues that need to be addressed to resolve the conflict.","t":"存在著需要解決的潛在問題，以解決這個衝突。"},{"w":"underprivileged","p":"adj.","d":"poor; not having the same chances as others","c":"弱勢的","s":"The organization focuses on providing support to underprivileged children in the community.","t":"該組織專注於為社區中的弱勢兒童提供支持。"},{"w":"underestimated","p":"adj.","d":"thought to be less than it really is","c":"被低估的","s":"Her skills were often underestimated, but she proved her capabilities.","t":"她的技能經常被低估，但她證明了自己的能力。"},{"w":"whereby","p":"adv.","d":"by which; through which","c":"藉由","s":"They devised a plan whereby they could achieve their goals more effectively.","t":"他們制定了一個計劃，藉由這個計劃他們可以更有效地實現自己的目標。"}]}];
